import sys
def main():
    data = sys.stdin.buffer.read().split()
    n = int(data[0]); m = int(data[1]); q = int(data[2])
    pos = 3
    edges = []
    for _ in range(m):
        edges.append((int(data[pos + 2]), int(data[pos]) - 1, int(data[pos + 1]) - 1))
        pos += 3
    edges.sort(reverse=True)
    qa = [0] * q; qb = [0] * q
    pending = [[] for _ in range(n)]
    for i in range(q):
        a = int(data[pos]) - 1; b = int(data[pos + 1]) - 1; pos += 2
        qa[i] = a; qb[i] = b
        pending[a].append(i); pending[b].append(i)
    parent = list(range(n))
    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root
    ans = [-1] * q
    for f, u, v in edges:
        ru = find(u); rv = find(v)
        if ru == rv:
            continue
        if len(pending[ru]) < len(pending[rv]):
            ru, rv = rv, ru
        parent[rv] = ru
        big = pending[ru]
        for qi in pending[rv]:
            if ans[qi] != -1:
                continue
            if find(qa[qi]) == find(qb[qi]):
                ans[qi] = f - 1
            else:
                big.append(qi)
        pending[rv] = []
    sys.stdout.write("\n".join(map(str, ans)) + "\n")
main()
